let language = localStorage.getItem("lappio-language") === "zh" ? "zh" : "en";
const page = document.body.dataset.page || "home";
const rootPrefix = page === "home" ? "./" : "../";
const searchDialog = document.querySelector("#search-dialog");
const searchInput = document.querySelector("#search-input");
const searchResults = document.querySelector("#search-results");
const friendNetwork = document.querySelector("#friend-network");
let selectedFriend = null;

function textFor(value) { return typeof value === "string" ? value : value[language]; }

function renderContent() {
  document.documentElement.lang = language === "zh" ? "zh-CN" : "en";
  document.querySelectorAll("[data-i18n]").forEach(node => {
    const value = copy[language][node.dataset.i18n];
    if (value === undefined) return;
    if (node.dataset.i18n === "aboutTitle") node.innerHTML = value;
    else node.textContent = value;
  });
  if (page !== "home") document.title = `${copy[language][`nav${page[0].toUpperCase()}${page.slice(1)}`]} · Lappio Blog`;
  document.querySelectorAll(".desktop-nav a, .mobile-nav a").forEach(link => {
    if (page !== "home" && link.getAttribute("href") === `${rootPrefix}${page}/`) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
  document.querySelector("#language-toggle").innerHTML = language === "en" ? "<strong>EN</strong> <span aria-hidden='true'>/</span> 中" : "EN <span aria-hidden='true'>/</span> <strong>中</strong>";
  document.querySelector("#language-toggle").setAttribute("aria-label",language === "en" ? "Switch to Chinese" : "切换到英文");
  document.querySelector("#search-open").setAttribute("aria-label",language === "en" ? "Search" : "搜索");
  document.querySelector("#search-open").title = language === "en" ? "Search" : "搜索";
  document.querySelector(".desktop-nav").setAttribute("aria-label",language === "en" ? "Main navigation" : "主导航");
  document.querySelector(".mobile-nav").setAttribute("aria-label",language === "en" ? "Mobile navigation" : "移动端导航");
  document.querySelector("#search-close").setAttribute("aria-label",language === "en" ? "Close search" : "关闭搜索");
  searchInput.placeholder = searchInput.dataset[`placeholder${language === "en" ? "En" : "Zh"}`];
  const blogList = document.querySelector("#blog-list");
  if (blogList) blogList.innerHTML = entries.blog.map((item,index) => `<article class="entry" id="blog-${index+1}"><div class="entry-meta">${language === "en" ? item.date : item.zhDate}</div><div><h3>${textFor(item.title)}</h3><p>${textFor(item.description)}</p></div></article>`).join("");
  const notesList = document.querySelector("#notes-list");
  if (notesList) notesList.innerHTML = entries.notes.map((item,index) => `<article class="note-card" id="note-${index+1}"><span class="tag">${textFor(item.tag)}</span><h3>${textFor(item.title)}</h3><div class="note-bottom"><span>${item.date}</span></div></article>`).join("");
  const projectsList = document.querySelector("#projects-list");
  if (projectsList) projectsList.innerHTML = entries.projects.map((item,index) => `<article class="project" id="project-${index+1}"><span class="project-number">0${index+1}</span><div><h3>${textFor(item.title)}</h3><p>${textFor(item.description)}</p></div></article>`).join("");
  if (friendNetwork) renderFriendNetwork();
  renderSearch();
}

function drawFriendLines() {
  if (!friendNetwork) return;
  const bounds = friendNetwork.getBoundingClientRect();
  const avatar = friendNetwork.querySelector(".avatar-ring").getBoundingClientRect();
  const centerX = avatar.left + avatar.width / 2 - bounds.left;
  const centerY = avatar.top + avatar.height / 2 - bounds.top;
  const svg = document.querySelector("#network-lines");
  svg.setAttribute("viewBox", `0 0 ${bounds.width} ${bounds.height}`);
  svg.querySelectorAll("line").forEach((line,index) => {
    const node = friendNetwork.querySelectorAll(".friend-node-avatar")[index].getBoundingClientRect();
    line.setAttribute("x1",centerX);
    line.setAttribute("y1",centerY);
    line.setAttribute("x2",node.left + node.width / 2 - bounds.left);
    line.setAttribute("y2",node.top + node.height / 2 - bounds.top);
  });
}

function selectFriend(index) {
  selectedFriend = index;
  const isOwnProfile = index === null;
  friendNetwork.querySelector("#profile-trigger").setAttribute("aria-pressed",String(isOwnProfile));
  friendNetwork.querySelector("#network-center").classList.toggle("is-selected",isOwnProfile);
  friendNetwork.querySelectorAll(".friend-node").forEach((node,nodeIndex) => {
    const isActive = !isOwnProfile && nodeIndex === index;
    node.classList.toggle("is-active",isActive);
    node.setAttribute("aria-pressed",String(isActive));
  });
  friendNetwork.querySelectorAll(".network-line").forEach((line,lineIndex) => line.classList.toggle("is-active",!isOwnProfile && lineIndex === index));
  const detail = document.querySelector("#friend-detail");
  detail.replaceChildren();
  detail.hidden = isOwnProfile;
  if (isOwnProfile) return;
  const friend = friendLinks[index];
  const copyBlock = document.createElement("div");
  const badge = document.createElement("small");
  badge.textContent = friend.url ? copy[language].friendTitle : copy[language].friendSampleBadge;
  const heading = document.createElement("h3");
  heading.textContent = textFor(friend.name);
  const description = document.createElement("p");
  description.textContent = textFor(friend.description);
  copyBlock.append(badge,heading,description);
  const action = friend.url ? document.createElement("a") : document.createElement("span");
  action.className = "friend-detail-action";
  action.textContent = friend.url ? copy[language].friendVisit : copy[language].friendNoUrl;
  if (friend.url) { action.href = friend.url; action.target = "_blank"; action.rel = "noopener noreferrer"; }
  detail.append(copyBlock,action);
}

function renderFriendNetwork() {
  const nodes = document.querySelector("#friend-nodes");
  const svg = document.querySelector("#network-lines");
  if (!nodes.childElementCount) {
    document.querySelector("#profile-trigger").addEventListener("click",()=>selectFriend(null));
    friendLinks.forEach((friend,index) => {
      const node = document.createElement("button");
      node.type = "button";
      node.className = "friend-node";
      node.style.setProperty("--x",`${friend.x}%`);
      node.style.setProperty("--y",`${friend.y}%`);
      node.addEventListener("click",()=>selectFriend(index));
      node.addEventListener("mouseenter",()=>svg.children[index].classList.add("is-hovered"));
      node.addEventListener("mouseleave",()=>svg.children[index].classList.remove("is-hovered"));
      node.addEventListener("focus",()=>svg.children[index].classList.add("is-hovered"));
      node.addEventListener("blur",()=>svg.children[index].classList.remove("is-hovered"));
      nodes.append(node);
      const line = document.createElementNS("http://www.w3.org/2000/svg","line");
      line.classList.add("network-line");
      svg.append(line);
    });
    if (friendAvatarSource) {
      const avatar = document.querySelector("#friend-avatar");
      const fallback = friendNetwork.querySelector(".avatar-placeholder");
      avatar.addEventListener("load",()=>{ avatar.hidden = false; fallback.hidden = true; });
      avatar.addEventListener("error",()=>{ avatar.hidden = true; fallback.hidden = false; });
      avatar.src = friendAvatarSource;
    }
    new ResizeObserver(drawFriendLines).observe(friendNetwork);
    if (document.fonts) document.fonts.ready.then(drawFriendLines);
  }
  document.querySelector("#profile-trigger").setAttribute("aria-label",copy[language].viewMyProfile);
  nodes.querySelectorAll(".friend-node").forEach((node,index) => {
    const friend = friendLinks[index];
    const avatar = document.createElement("span");
    avatar.className = "friend-node-avatar";
    if (friend.avatar) {
      const image = document.createElement("img");
      image.src = friend.avatar;
      image.alt = "";
      avatar.append(image);
    } else avatar.textContent = String(index+1).padStart(2,"0");
    const name = document.createElement("strong");
    name.textContent = textFor(friend.name);
    node.replaceChildren(avatar,name);
    node.setAttribute("aria-label",`${textFor(friendLinks[index].name)} — ${textFor(friendLinks[index].description)}`);
  });
  selectFriend(selectedFriend);
  requestAnimationFrame(drawFriendLines);
}

function renderSearch() {
  const query = searchInput.value.trim().toLocaleLowerCase();
  if (!query) { searchResults.innerHTML = `<div class="search-empty">${copy[language].searchStart}</div>`; return; }
  const records = [
    ...entries.blog.map((item,index)=>({type:copy[language].blogLabel,title:textFor(item.title),description:textFor(item.description),target:`${rootPrefix}blog/#blog-${index+1}`})),
    ...entries.notes.map((item,index)=>({type:copy[language].noteLabel,title:textFor(item.title),description:"",target:`${rootPrefix}notes/#note-${index+1}`})),
    ...entries.projects.map((item,index)=>({type:copy[language].projectLabel,title:textFor(item.title),description:textFor(item.description),target:`${rootPrefix}projects/#project-${index+1}`}))
  ];
  const matches = records.filter(item => `${item.title} ${item.description} ${item.type}`.toLocaleLowerCase().includes(query));
  searchResults.replaceChildren();
  if (!matches.length) { const empty=document.createElement("div");empty.className="search-empty";empty.textContent=copy[language].noResults;searchResults.append(empty);return; }
  matches.forEach(item => { const link=document.createElement("a");link.className="search-result";link.href=item.target;const label=document.createElement("small");label.textContent=item.type;const title=document.createElement("strong");title.textContent=item.title;link.append(label,title);link.addEventListener("click",()=>searchDialog.close());searchResults.append(link); });
}

document.querySelector("#language-toggle").addEventListener("click",()=>{ language = language === "en" ? "zh" : "en"; localStorage.setItem("lappio-language",language);renderContent(); });
document.querySelector("#search-open").addEventListener("click",()=>{ searchDialog.showModal();searchInput.focus(); });
document.querySelector("#search-close").addEventListener("click",()=>searchDialog.close());
searchDialog.addEventListener("click",event=>{ if(event.target===searchDialog) searchDialog.close(); });
searchInput.addEventListener("input",renderSearch);
document.addEventListener("keydown",event=>{ if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="k"){event.preventDefault();searchDialog.open ? searchDialog.close() : (searchDialog.showModal(),searchInput.focus());} });
document.querySelector("#year").textContent=new Date().getFullYear();
renderContent();
if (page === "links" && !window.location.hash) {
  const centerProfile = () => requestAnimationFrame(() => requestAnimationFrame(() => {
    if (window.scrollY > 40) return;
    const avatar = document.querySelector("#profile-trigger .avatar-ring").getBoundingClientRect();
    const avatarCenter = window.scrollY + avatar.top + avatar.height / 2;
    const previousBehavior = document.documentElement.style.scrollBehavior;
    document.documentElement.style.scrollBehavior = "auto";
    window.scrollTo(0,Math.max(0,avatarCenter - window.innerHeight / 2));
    document.documentElement.style.scrollBehavior = previousBehavior;
  }));
  if (document.readyState === "complete") centerProfile();
  else window.addEventListener("load",centerProfile,{once:true});
}
